395	type MailDispatchRelease = () => Promise<void>;
396	type MailDispatchActivation = () => Promise<MailDispatchRelease>;
397	
398	interface WaitingMailDispatch {
399	  readonly resolve: (activate: MailDispatchActivation) => void;
400	  readonly reject: (error: AuthFlowError) => void;
401	  readonly timeout: ReturnType<typeof setTimeout>;
402	  readonly minimumReservationMs: number;
