418	/**
419	 * The route-owned refusal-audit persistence coordinator: one ordered queue, one
420	 * writer, one advancing window.
421	 */
422	interface RefusalAuditCoordinator {
423	  /**
424	   * Finalized aggregates awaiting their UNIQUE durable write, oldest window
425	   * first. The limiter has already released every entry here, so this array is
426	   * the last copy of that refusal evidence: an entry leaves only once its own
427	   * write has landed.
428	   */
429	  readonly queue: Readonly<RefusalAggregate>[];
430	  /**
431	   * The one window still accumulating inside the limiter, with the timer that
432	   * finalizes it at its aggregation deadline. Rollover ADVANCES this field and
433	   * touches nothing else.
434	   */
435	  active: Readonly<{
436	    windowStartedAt: number;
437	    timer: ReturnType<typeof setTimeout>;
438	  }> | undefined;
439	  /**
440	   * THE writer for this route while one is running. Every path — the public
441	   * refusal, the deadline timer, and every concurrent shutdown drain — joins
442	   * this exact promise rather than starting a private one, which is what makes
443	   * a second write of an in-flight window impossible and makes a drain unable
444	   * to return while this route still owes a write.
445	   */
446	  writer: Promise<void> | undefined;
447	}
448	
449	function sourceContext(source: AuthSourceContext): AuthSourceContext {
450	  if (source.ip.trim() === "" || source.requestId.trim() === "") {
451	    throw new AuthFlowError("AUTH_INPUT_INVALID");
452	  }
453	  const userAgent = source.userAgent.trim();
454	  return Object.freeze({
455	    ip: source.ip.slice(0, 64),
456	    userAgent: (userAgent === "" ? "unknown" : userAgent).slice(0, 256),
457	    requestId: source.requestId.slice(0, 128)
458	  });
459	}
