461	export class RegistrationService implements RegistrationApplication {
462	  private readonly clock: () => Date;
463	  private readonly sleep: (milliseconds: number) => Promise<void>;
464	  private readonly pendingMailDispatches = new Set<Promise<void>>();
465	  private readonly waitingMailDispatches: WaitingMailDispatch[] = [];
466	  private mailDispatchReservations = 0;
467	  private nextMailDispatchActivationAt = Number.NEGATIVE_INFINITY;
468	  private registrationHashesActive = 0;
469	  private readonly waitingRegistrationHashes: Array<() => void> = [];
470	  private mailCapacitySignalAggregate: MailCapacitySignalAggregate | undefined;
471	  /**
472	   * ONE persistence coordinator per route, stable across every window.
473	   *
474	   * A refusal window that rolls over is the hard case: W0 stops accumulating
475	   * the instant W1 opens, and from that moment exactly one owner must carry W0
476	   * to a durable row. Giving each window its own queue and its own writer is
477	   * what produced two owners (a superseded window's aggregates shallow-copied
478	   * into a successor that writes them again behind the still-unresolved
479	   * predecessor) or none (a rollover snapshot awaited on the public path and
480	   * discarded when its write failed).
481	   *
482	   * So the queue and the writer belong to the ROUTE and only the active window
483	   * advances. Nothing here is ever replaced or copied on rollover.
484	   */
485	  private readonly refusalAuditRoutes = new Map<AuthRoute, RefusalAuditCoordinator>();
486	
487	  constructor(private readonly dependencies: {
488	    readonly repository: IdentityRepository;
489	    readonly mail: MailSender;
490	    readonly dekStore: UserDekStore;
491	    readonly blindIndexKey: Uint8Array;
492	    readonly policy: AuthPolicy;
493	    readonly limiter: InProcessAuthRateLimiter;
494	    /**
495	     * Off-thread Argon2. Injected, never constructed here: exactly one
496	     * process-owned pool is created in main.ts and shared with the repository,
497	     * so there is no module singleton, pool-per-request or second pool.
498	     */
499	    readonly argon2: Argon2Executor;
500	    readonly clock?: () => Date;
501	    readonly sleep?: (milliseconds: number) => Promise<void>;
502	    readonly verificationTokenFactory?: () => string;
503	  }) {
504	    this.clock = dependencies.clock ?? (() => new Date());
505	    this.sleep = dependencies.sleep ?? (async (milliseconds) => {
506	      await new Promise<void>((resolve) => setTimeout(resolve, milliseconds));
507	    });
508	  }
509	
510	  private async holdEnumerationFloor(startedAt: number): Promise<void> {
511	    const remaining = this.dependencies.policy.verification.enumerationResponseFloorMs
512	      - (performance.now() - startedAt);
513	    if (remaining > 0) await this.sleep(remaining);
514	  }
515	
516	  private async holdRegistrationEnumerationClamp(startedAt: number): Promise<void> {
517	    const clampMs = this.dependencies.policy.verification.enumerationResponseFloorMs
518	      + this.dependencies.policy.verification.enumerationToleranceMs;
519	    const remaining = clampMs - (performance.now() - startedAt);
520	    if (remaining > 0) await this.sleep(remaining);
521	  }
522	
523	  private startNextRegistrationHash(): void {
524	    if (this.registrationHashesActive
525	      >= this.dependencies.policy.channel.maxConcurrentRegistrationHashes) return;
526	    this.waitingRegistrationHashes.shift()?.();
527	  }
528	
529	  private scheduleRegistrationHash(password: string): RegistrationHashWork {
530	    let passwordValue: string | undefined = password;
531	    let started = false;
532	    let settled = false;
533	    let rejectWork!: (error: unknown) => void;
534	    let start!: () => void;
535	    const promise = new Promise<string>((resolve, reject) => {
536	      rejectWork = reject;
537	      start = () => {
538	        if (settled) return;
539	        started = true;
540	        this.registrationHashesActive += 1;
541	        const value = passwordValue!;
542	        passwordValue = undefined;
543	        void hashPassword(this.dependencies.argon2, value, this.dependencies.policy.password.argon2id)
544	          .then((hash) => {
545	            settled = true;
546	            resolve(hash);
547	          }, (error: unknown) => {
548	            settled = true;
549	            reject(error);
550	          })
551	          .finally(() => {
552	            this.registrationHashesActive -= 1;
553	            this.startNextRegistrationHash();
554	          });
555	      };
556	    });
557	    if (this.registrationHashesActive
558	      < this.dependencies.policy.channel.maxConcurrentRegistrationHashes) {
559	      start();
560	    } else {
561	      this.waitingRegistrationHashes.push(start);
562	    }
563	    return Object.freeze({
564	      promise,
565	      cancel: () => {
566	        if (started || settled) return;
567	        const index = this.waitingRegistrationHashes.indexOf(start);
568	        if (index >= 0) this.waitingRegistrationHashes.splice(index, 1);
569	        passwordValue = undefined;
570	        settled = true;
571	        rejectWork(new Error("REGISTRATION_HASH_CANCELLED"));
572	      }
573	    });
574	  }
575	
576	  private async recordRefusalAggregate(route: AuthRoute, aggregate: Readonly<RefusalAggregate>): Promise<void> {
577	    await this.dependencies.repository.recordRateLimitRefusal({
578	      actorToken: aggregate.actorToken,
579	      route,
580	      scope: aggregate.ipCount > 0 ? "ip" : "address",
581	      count: aggregate.count,
582	      ipCount: aggregate.ipCount,
