599	  /**
600	   * Cleanup is allowed ONLY once this route owns nothing: no accumulating
601	   * window, no aggregate still awaiting its row, no write in flight. Dropping
602	   * the coordinator any earlier would drop the only copy of that evidence.
603	   */
604	  private releaseRefusalAuditRoute(route: AuthRoute): void {
605	    const coordinator = this.refusalAuditRoutes.get(route);
606	    if (coordinator !== undefined && coordinator.active === undefined
607	      && coordinator.queue.length === 0 && coordinator.writer === undefined) {
608	      this.refusalAuditRoutes.delete(route);
