861	  private reserveMailDispatchPermit(
862	    correlationId: string,
863	    minimumReservationMs: number = this.dependencies.policy.channel.mailDispatchMinimumReservationMs,
864	    activationSpacingMs: number = this.dependencies.policy.channel.mailDispatchActivationSpacingMs
865	  ): Promise<MailDispatchActivation> {
866	    if (this.mailDispatchReservations < this.dependencies.policy.channel.maxConcurrentVerificationDispatches) {
867	      this.mailDispatchReservations += 1;
868	      return Promise.resolve(() => this.scheduleMailDispatchActivation(
869	        false, minimumReservationMs, activationSpacingMs
870	      ));
871	    }
872	    if (this.waitingMailDispatches.length >= this.dependencies.policy.channel.maxQueuedVerificationDispatches) {
873	      this.signalMailCapacity(correlationId);
874	      throw new AuthFlowError("AUTH_MAIL_BUSY");
875	    }
876	    return new Promise<MailDispatchActivation>((resolve, reject) => {
877	      let waiting!: WaitingMailDispatch;
878	      const timeout = setTimeout(() => {
879	        const index = this.waitingMailDispatches.indexOf(waiting);
880	        if (index < 0) return;
881	        this.waitingMailDispatches.splice(index, 1);
882	        this.signalMailCapacity(correlationId);
883	        reject(new AuthFlowError("AUTH_MAIL_BUSY"));
884	      }, this.dependencies.policy.channel.mailDispatchQueueWaitTimeoutMs);
885	      waiting = Object.freeze({
886	        resolve, reject, timeout, minimumReservationMs, activationSpacingMs
887	      });
888	      this.waitingMailDispatches.push(waiting);
889	    });
890	  }
