913	  private async refuseRateLimit(input: {
914	    readonly route: AuthRoute;
915	    readonly scope: "ip" | "address";
916	    readonly actorToken: string;
917	    readonly now: Date;
918	    readonly source: AuthSourceContext;
919	  }): Promise<never> {
920	    const aggregate = this.dependencies.limiter.aggregateRefusal(input);
921	    if (aggregate.finalized !== null) {
922	      // Rollover. The limiter has just released the previous window, so this
923	      // snapshot is the only copy: it goes to the route coordinator ONCE, and
924	      // the timer that armed that window will decline to finalize it again
925	      // because it is no longer the active one.
926	      this.enqueueRefusalAggregate(input.route, aggregate.finalized);
927	    }
928	    if (aggregate.startedWindow) {
929	      this.scheduleRefusalAuditFlush(input.route, aggregate.windowStartedAt, input.now);
930	    }
931	    if (aggregate.finalized !== null) {
932	      // FIRE-AND-FORGET, never awaited. A rate-limit refusal is a public path:
933	      // an ordinary opaque 429 must not be gated on a database write. The
934	      // shared route writer carries the snapshot in the background, and a
935	      // shutdown drain joins this exact promise, so declining to wait here
936	      // loses no evidence and hides no failure.
937	      void this.startRefusalAuditPump(input.route).catch(() => {
938	        console.error(
939	          `[AUTH_RATE_LIMIT_AUDIT_RECORD_FAILED] route=${input.route} window=${new Date(aggregate.finalized!.windowStartedAt).toISOString()}`
940	        );
941	      });
942	    }
943	    throw new AuthFlowError("AUTH_RATE_LIMITED");
944	  }
