      "+113.1, +111.2 and +75.4 ms", "N=4 is deliberately NOT claimed",
      "+7.0, +9.2 and -6.5 ms", "[4,4,3]", "[8,8,4]",
      "not a monotone lower bound", "exactly 103", "103/103/103", "100/100/100"
    ]) {
