      for (let index = 0; index < legacyAddressBudget; index += 1) {
        expect(limiter.consume({
          route,
          ip: `attacker:${route}:${index}`,
          addressKey: "victim:address",
          now: new Date(0)
        })).toEqual({ allowed: true });
      }
      for (let index = 0; index < routePolicy.admissionPerSource; index += 1) {
        expect(limiter.consume({
          route,
