    },
    recordVerificationDeliveryRecordFailure: async () => {
      counters.repository += 1;
      counters.deliveryAudit += 1;
    },
    recordDuplicateRegistrationPostwork: async () => {
      counters.repository += 1;
      counters.deliveryAudit += 1;
    },
    consumeVerification: async () => {
      counters.repository += 1;
