      `, [existingTokens.rows.map((row) => row.audit_token)]);
      cells.push(
        `n=${concurrency} existing=[${existing.map((value) => value.toFixed(1)).join(",")}] `
        + `missing=[${missing.map((value) => value.toFixed(1)).join(",")}] `
