    if (registrationCadenceMs === 45) {
      const channelRow = AUTH_POLICY_REGISTER_ROWS
        .find((row) => row.rowKey === "channelPolicy")!;
      const dispatch = (channelRow.value as {
        verification_dispatch: {
          sizing_derivation: string;
