    expect(hundred.committed).toBe(100);
    expect(hundred.sends).toBe(100);
    expect(hundred.queueDeadlineMarginMs).toBeGreaterThanOrEqual(0);

    // The EXACT ruled accepted-request capacity. Three fresh isolated repeats
    // accepted 103/103/103 at both 128 and 160, so this is a measured constant
    // and not an inequality: a burst deeper than the 32 in-flight + 96 queued
    // structure can absorb neither gains nor loses admissions.
    const capacity = basePolicy.channel.measuredAcceptedRequestCapacity;
    expect(capacity).toBe(103);
    for (const size of [128, 160]) {
      const overload = measurements.find((measurement) => measurement.size === size)!;
      expect(overload.successes).toBe(capacity);
