      expect(basePolicy.channel.currentClampAbsorptionDecisionVersion).toBe(2);
      expect(basePolicy.channel.currentMaximumClampAbsorbedRegistrationConcurrency).toBe(3);
      expect(basePolicy.channel.currentRegistrationHashAndProvisioningUpperBoundMs).toBe(430);
      expect(basePolicy.channel.currentRegistrationClampHeadroomMs).toBe(35);
      expect(absorbed.hashAndProvisioningMaximumMs).toBeLessThanOrEqual(
