    expect(overload.queueDeadlineMarginMs).toBeGreaterThanOrEqual(0);
  }
  // Nothing leaks: every burst ends with the budget fully returned.
  for (const measurement of measurements) {
    expect(measurement.admittedAfterDrain).toBe(0);
  }
}, 600_000);

