      }

      console.info(
        `[T1 REWORK2 CLAMP ABSORPTION decision_version=2] cadence_ms=${registrationCadenceMs} `
        + `n_star=${basePolicy.channel.currentMaximumClampAbsorbedRegistrationConcurrency} `
        + `ruled_upper_ms=${basePolicy.channel.currentRegistrationHashAndProvisioningUpperBoundMs} `
        + `ruled_headroom_ms=${basePolicy.channel.currentRegistrationClampHeadroomMs} `
        + `observed_n3_hash_provision_max_ms=${absorbed.hashAndProvisioningMaximumMs.toFixed(1)} `
