      );
      writeHeapSnapshot(snapshotPath);
      const counts = await retainedDispatcherShapeCounts(snapshotPath);
      await rm(snapshotPath, { force: true });
      return counts;
    };
    const refuseThrough = async (start: number, end: number): Promise<void> => {
      let busy = 0;
