      + `controlled_dek_latency_ms=${branchOnlyDelayMs} `
      + `n1_existing=${n1Existing.map((value) => value.toFixed(1)).join(",")} `
      + `n1_missing=${n1Missing.map((value) => value.toFixed(1)).join(",")} n1_gap=${n1Gap.toFixed(1)} `
